#include <iostream>
using namespace std;

class Room
{
private:
    double length;
    double width;
public:
    void setLength(double);
    void setWidth(double);
    double getArea() const;
    double getPerimeter() const;
};

void Room::setLength(double len)
{
    length = len;
}

void Room::setWidth(double w)
{
    width = w;
}

double Room::getArea() const
{
    return length * width;
}

double Room::getPerimeter() const
{
    return 2 * (length + width);
}

int main()
{
    double l, w;
    Room room;

    cin >> l >> w;
    room.setLength(l);
    room.setWidth(w);

    cout << "Area: " << room.getArea() << endl;
    cout << "Perimeter: " << room.getPerimeter() << endl;
    return 0;
}

#include <iostream>
using namespace std;

class Account
{
private:
    double balance;
public:
    Account();
    Account(double);
    void deposit(double);
    bool withdraw(double);
    double getBalance() const;
};

Account::Account()
{
    balance = 0;
}

Account::Account(double start)
{
    balance = start;
}

void Account::deposit(double amount)
{
    if (amount > 0)
        balance += amount;
}

bool Account::withdraw(double amount)
{
    if (amount > 0 && amount <= balance)
    {
        balance -= amount;
        return true;
    }
    return false;
}

double Account::getBalance() const
{
    return balance;
}

int main()
{
    Account a(100);
    Account b;
    double dep, w1, w2;

    cin >> dep >> w1 >> w2;
    a.deposit(dep);
    if (!a.withdraw(w1))
        cout << "Withdrawal of " << w1 << " refused" << endl;
    a.withdraw(w2);

    cout << "Balance: " << a.getBalance() << endl;
    cout << "Empty account: " << b.getBalance() << endl;
    return 0;
}
